To create a Discord bot using Discord.js v14 with the specified functionality, you'll need to follow these steps:

1. Set up your bot and get your bot token.
2. Create a new file for your bot's code.
3. Write the necessary code for the `ban` and `unban` slash commands.
4. Implement checks to ensure the bot can only ban users with roles lower than its own role.

Here's a complete example of how you can implement this:

1. **Install Discord.js**:
   Make sure you have Node.js and npm installed. Then, run the following command in your project directory to install Discord.js:

   ```bash
   npm install discord.js
   ```

2. **Create your bot file** (e.g., `bot.js`):

```javascript
const { Client, SlashCommandBuilder, REST, Routes } = require('discord.js');
const { token } = require('./config.json'); // Make sure to create a config.json file with your token

const client = new Client({ intents: ['GUILDS', 'GUILD_MESSAGES'] });

const rest = new REST({ version: '10' }).setToken(token);

client.once('ready', () => {
    console.log(`Logged in as ${client.user.tag}`);
});

client.on('interactionCreate', async (interaction) => {
    if (!interaction.isChatInputCommand()) return;

    if (interaction.commandName === 'ban') {
        await interaction.deferReply({ ephemeral: true });

        const userId = interaction.options.getString('user_id');
        const reason = interaction.options.getString('reason') || 'No reason provided';

        try {
            if (!userId || !reason) {
                await interaction.editReply('Please provide a valid user ID and a reason.');
                return;
            }

            const member = await interaction.guild.members.fetch(userId);
            if (!member) {
                await interaction.editReply('User not found.');
                return;
            }

            if (member.id === client.user.id || member.id === interaction.user.id) {
                await interaction.editReply('You cannot ban yourself or the bot.');
                return;
            }

            if (member.roles.highest.position >= interaction.guild.members.me.roles.highest.position) {
                await interaction.editReply('You cannot ban someone with a higher or equal role than yours.');
                return;
            }

            await member.ban({ reason });
            await interaction.editReply(`User <@${userId}> has been banned for: ${reason}.`);
        } catch (error) {
            await interaction.editReply(`An error occurred: ${error.message}`);
        }
    }

    if (interaction.commandName === 'unban') {
        await interaction.deferReply({ ephemeral: true });

        const userId = interaction.options.getString('user_id');

        try {
            if (!userId) {
                await interaction.editReply('Please provide a valid user ID.');
                return;
            }

            const bannedUser = await interaction.guild.bans.fetch(userId);
            if (!bannedUser) {
                await interaction.editReply('User not found.');
                return;
            }

            await interaction.guild.members.unban(userId);
            await interaction.editReply(`User <@${userId}> has been unbanned.`);
        } catch (error) {
            await interaction.editReply(`An error occurred: ${error.message}`);
        }
    }
});

const commands = [
    new SlashCommandBuilder()
        .setName('ban')
        .setDescription('Ban a user.')
        .addStringOption(option => option.setName('user_id').setDescription('The user ID to ban').setRequired(true))
        .addStringOption(option => option.setName('reason').setDescription('The reason for banning the user')),
    new SlashCommandBuilder()
        .setName('unban')
        .setDescription('Unban a user.')
        .addStringOption(option => option.setName('user_id').setDescription('The user ID to unban').setRequired(true)),
];

(async () => {
    try {
        await rest.put(
            Routes.applicationCommands(client.user.id, client.application.id),
            { body: commands }
        );
        console.log('Commands have been registered.');
    } catch (error) {
        console.error(error);
    }
})();

client.login(token);
```

